#include "ModMenu/View.h"
#include "ModMenu/Workspace.h"
#include <iostream>
int main(){using namespace menu;Menu m;m.open=true;m.entries.push_back({"Example","Example","1","Author","Demo","Loaded","",true,false,{}});
 auto definition=ParseWorkspace(R"({"schemaVersion":1,"plugin":{"id":"Example","entry":"Example.dll","versions":["1"]},"pages":[{"id":"jobs","label":"Jobs","controls":[{"id":"start","type":"action","label":"Start"}]}]})","Example","Example.dll","1");
 auto session=Workspaces().Register(definition);Workspaces().Publish(session,R"({"protocolVersion":1,"revision":1,"controls":{"start":{"enabled":true}}})");
 m.workspaces=Workspaces().Snapshots();Frame f{640,360,true,true,false,MenuScene::Main};auto view=BuildView(m,f);bool found=false;for(auto const&p:view)found|=p.text=="Workspace";if(!found){std::cerr<<"FAIL registered plugin has no Workspace entry\n";return 1;}
 int failures=0;auto check=[&](bool ok,char const*t){if(!ok){++failures;std::cerr<<"FAIL "<<t<<'\n';}};auto layout=Arrange(m.config,f);m.Input({Kind::Down,layout.configure.x+5,layout.configure.y+5,1,1},f);m.Input({Kind::Up,layout.configure.x+5,layout.configure.y+5,1,0},f);check(m.workspaceOpen,"paired click opens selected workspace");
 std::uint32_t n=0;for(int i=0;i<100;++i)BuildView(m,f);Workspaces().Poll(session,nullptr,0,n);check(n==0,"100 renders never enqueue action");
 m.Input({Kind::Down,20,65,1,1},f);m.Input({Kind::Up,20,65,1,0},f);Workspaces().Poll(session,nullptr,0,n);check(n>0,"paired control click enqueues explicit action");
 m.Input({Kind::Key,0,0,27,1},f);check(!m.workspaceOpen&&m.open,"Escape returns to Mods not game");Workspaces().Poll(session,nullptr,0,n);check(n>0,"closing page does not discard queued work");
 auto d=ParseWorkspace(R"({"schemaVersion":1,"plugin":{"id":"Images","entry":"Images.dll","versions":["1"]},"pages":[{"id":"map","label":"Map","controls":[{"id":"pixels","type":"image","label":"Pixels"}]}]})","Images","Images.dll","1");auto imageSession=Workspaces().Register(d);WorkspaceJson state={{"protocolVersion",1},{"revision",1},{"controls",{{"pixels",{{"width",64},{"height",48},{"pixels",WorkspaceJson::array()}}}}}};for(unsigned i=0;i<3072;++i)state["controls"]["pixels"]["pixels"].push_back(i%2?0xFF0000FFu:0x00FF00FFu);check(Workspaces().Publish(imageSession,state.dump()),"max bounded image accepted");
 for(auto const&s:Workspaces().Snapshots())if(s.session==imageSession)m.workspace.Open(s);m.workspaceOpen=true;
 for(auto size:{std::pair{240.f,160.f},std::pair{320.f,180.f},std::pair{640.f,360.f},std::pair{854.f,480.f}}){f.width=size.first;f.height=size.second;auto paints=BuildView(m,f);bool bounded=true;for(auto const&p:paints)bounded&=p.rect.x>=0&&p.rect.y>=0&&p.rect.x+p.rect.w<=f.width+.01f&&p.rect.y+p.rect.h<=f.height+.01f;check(bounded,"pixel paint remains within viewport");check(paints.size()>3000,"pixel preview available even at compact size");}
 auto confirmed=ParseWorkspace(R"({"schemaVersion":1,"plugin":{"id":"Confirm","entry":"Confirm.dll","versions":["1"]},"pages":[{"id":"jobs","label":"Jobs","controls":[{"id":"erase","type":"action","label":"Clear","confirmation":"Really clear?"}]}]})","Confirm","Confirm.dll","1");auto token=Workspaces().Register(confirmed);Workspaces().Publish(token,R"({"protocolVersion":1,"revision":1,"controls":{"erase":{"enabled":true}}})");WorkspaceUi ui;for(auto const&s:Workspaces().Snapshots())if(s.session==token)ui.Open(s);f={640,360,true,true,false,MenuScene::Main};ui.Input({Kind::Down,20,65,1,1},f,false);ui.Input({Kind::Up,20,65,1,0},f,false);Workspaces().Poll(token,nullptr,0,n);check(!ui.confirmation.empty()&&n==0,"dangerous action waits for confirmation");ui.Input({Kind::Key,0,0,27,1},f,false);Workspaces().Poll(token,nullptr,0,n);check(ui.confirmation.empty()&&n==0,"Escape cancels confirmation only");
 ui.Input({Kind::Down,20,65,1,1},f,false);f.width=320;ui.Input({Kind::Up,20,65,1,0},f,false);check(ui.confirmation.empty(),"resize cancels paired press before activation");
 f.width=640;ui.Input({Kind::Down,20,65,1,1},f,false);ui.Input({Kind::Up,20,65,1,0},f,false);ui.Input({Kind::Key,0,0,13,1},f,false);Workspaces().Poll(token,nullptr,0,n);check(n>0&&ui.confirmation.empty(),"explicit keyboard confirmation queues dangerous action");
 auto listDef=ParseWorkspace(R"({"schemaVersion":1,"plugin":{"id":"ListUi","entry":"ListUi.dll","versions":["1"]},"pages":[{"id":"results","label":"Results","controls":[{"id":"list","type":"list","label":"Results","selectAction":"choose"}]}]})","ListUi","ListUi.dll","1");auto listToken=Workspaces().Register(listDef);Workspaces().Publish(listToken,R"({"protocolVersion":1,"revision":1,"controls":{"list":{"rows":[{"id":"r0","label":"Zero"},{"id":"r1","label":"One"},{"id":"r2","label":"Two","enabled":false,"reason":"Result unavailable"}]}}})");WorkspaceUi listUi;for(auto const&s:Workspaces().Snapshots())if(s.session==listToken)listUi.Open(s);
 listUi.Input({Kind::Wheel,0,0,0,-2},f,false);listUi.Input({Kind::Down,20,65,1,1},f,false);listUi.Input({Kind::Up,20,65,1,0},f,false);Workspaces().Poll(listToken,nullptr,0,n);std::vector<char>selected(n);check(n&&Workspaces().Poll(listToken,selected.data(),n,n)&&WorkspaceJson::parse(selected.data())["rowId"]=="r1","scrolled list selection submits stable row ID not visible index");
 auto textDef=ParseWorkspace(R"({"schemaVersion":1,"plugin":{"id":"Forms","entry":"Forms.dll","versions":["1"]},"pages":[{"id":"form","label":"Form","controls":[{"id":"name","type":"text","label":"Name","minBytes":0,"maxBytes":64}]}]})","Forms","Forms.dll","1");WorkspaceSnapshot empty{999,std::make_shared<WorkspaceDefinition const>(textDef),{}, {}};WorkspaceUi form;form.Open(empty);empty.state=std::make_shared<WorkspaceJson const>(WorkspaceJson::parse(R"({"protocolVersion":1,"revision":1,"controls":{"name":{"value":"Initial"}}})"));form.Accept(empty);check(form.values["name"]=="Initial","first delayed snapshot initializes form values");
 // A fresh snapshot between mouse-down and release must not silently change
 // the operation the user was about to submit.
 auto freshToken=Workspaces().Register(ParseWorkspace(R"({"schemaVersion":1,"plugin":{"id":"Refresh","entry":"Refresh.dll","versions":["1"]},"pages":[{"id":"jobs","label":"Jobs","controls":[{"id":"start","type":"action","label":"Start"}]}]})","Refresh","Refresh.dll","1"));
 Workspaces().Publish(freshToken,R"({"protocolVersion":1,"revision":1,"controls":{"start":{"enabled":true}}})");
 WorkspaceUi refresh;for(auto const&s:Workspaces().Snapshots())if(s.session==freshToken)refresh.Open(s);
 refresh.Input({Kind::Down,20,65,1,1},f,false);
 Workspaces().Publish(freshToken,R"({"protocolVersion":1,"revision":2,"controls":{"start":{"enabled":true}}})");for(auto const&s:Workspaces().Snapshots())if(s.session==freshToken)refresh.Accept(s);
 refresh.Input({Kind::Up,20,65,1,0},f,false);Workspaces().Poll(freshToken,nullptr,0,n);check(n==0,"snapshot refresh invalidates paired action press");
 refresh.Input({Kind::Down,20,65,1,1},f,false);refresh.Input({Kind::Up,20,65,1,0},f,false);Workspaces().Poll(freshToken,nullptr,0,n);check(n>0,"fresh paired action remains available after refresh");
 std::vector<char>resultCommand(n);Workspaces().Poll(freshToken,resultCommand.data(),n,n);auto resultId=WorkspaceJson::parse(resultCommand.data())["requestId"];
 Workspaces().Publish(freshToken,WorkspaceJson{{"protocolVersion",1},{"revision",3},{"controls",{{"start",{{"enabled",true}}}}},{"results",{{{"requestId",resultId},{"state","failed"},{"message",{{"en_US","Sample job failed"},{"zh_TW","工作失敗"}}}}}}}.dump());for(auto const&s:Workspaces().Snapshots())if(s.session==freshToken)refresh.Accept(s);
 bool resultShown=false;for(auto const&p:refresh.View(f,Locale::English))resultShown|=p.text=="Sample job failed";check(resultShown,"provider terminal result replaces waiting notice");
 resultShown=false;for(auto const&p:refresh.View(f,Locale::TraditionalChinese))resultShown|=p.text=="工作失敗";check(resultShown,"provider terminal result follows game locale");
 // Clipboard completion may not cross editor/page generations or domains.
 Menu clip;clip.open=clip.workspaceOpen=true;clip.workspace.Open(empty);clip.workspace.Input({Kind::Down,20,65,1,1},f,false);clip.workspace.Input({Kind::Up,20,65,1,0},f,false);clip.workspace.Input({Kind::Key,0,0,35,1},f,false);auto generation=clip.workspace.editGeneration;
 clip.CompleteClipboard((std::uint64_t(1)<<63)|generation,"中");check(clip.workspace.editor.value=="Initial中","matching workspace paste generation inserts UTF8");
 clip.CompleteClipboard(generation,"wrong");check(clip.workspace.editor.value=="Initial中","Configure clipboard domain cannot paste into workspace");
 clip.workspace.editor.SelectAll();clip.CompleteClipboard((std::uint64_t(1)<<63)|generation,"");check(clip.workspace.editor.value=="Initial中"&&!clip.workspace.notice.empty(),"empty or rejected clipboard preserves selected text and reports failure");
 clip.workspace.Input({Kind::Key,0,0,27,1},f,false);clip.CompleteClipboard((std::uint64_t(1)<<63)|generation,"late");check(clip.workspace.values["name"]=="Initial","late cancelled paste cannot alter stored form");
 std::cout<<"workspace UI failures="<<failures<<'\n';return failures?1:0;
}
